package dev.bennett.codexmeter;

import android.app.*;import android.content.*;import android.content.pm.*;import android.database.Cursor;import android.database.sqlite.*;import android.os.*;import org.json.*;import java.time.*;

/** Only the newly allocated owned stable AVD, with synthetic credentials and legacy records. */
public final class Stable311ContinuityNativeTest extends Instrumentation {
 String phase;int checks;void check(boolean b,String why){checks++;if(!b)throw new AssertionError(why);}
 @Override public void onCreate(Bundle args){super.onCreate(args);phase=args.getString("phase","verify");start();}
 static JSONObject raw(Context c,String account)throws Exception{try(SQLiteDatabase db=SQLiteDatabase.openDatabase(c.getDatabasePath(RpgProgressStore.NAME).getPath(),null,SQLiteDatabase.OPEN_READONLY);Cursor row=db.rawQuery("SELECT document FROM profiles WHERE account=?",new String[]{account})){if(!row.moveToFirst())throw new AssertionError("Missing original profile");return new JSONObject(row.getString(0));}}
 static JSONArray observations(Context c)throws Exception{JSONArray rows=new JSONArray();try(SQLiteDatabase db=SQLiteDatabase.openDatabase(c.getDatabasePath(UsageLedgerDatabase.NAME).getPath(),null,SQLiteDatabase.OPEN_READONLY);Cursor cur=db.rawQuery("SELECT meter,policy,observed_at,used_decimal,reset_at,source,manual FROM observations ORDER BY meter,observed_at",null)){while(cur.moveToNext()){JSONArray row=new JSONArray();for(int i=0;i<cur.getColumnCount();i++)row.put(cur.getString(i));rows.put(row);}}return rows;}
 @Override public void onStart(){Context c=getTargetContext();Bundle out=new Bundle();try{
  check(Build.MODEL.contains("sdk")&&c.getPackageName().equals("dev.bennett.codexmeter"),"Owned stable sandbox only");PackageInfo info=c.getPackageManager().getPackageInfo(c.getPackageName(),0);SharedPreferences qa=c.getSharedPreferences("stable311_upgrade_qa",0);
  if(phase.equals("seed")){
   check(info.versionName.equals("3.1.0")&&info.getLongVersionCode()==87,"Published stable3.1.0/code87");AuthTokens prior=SecureTokenStore.load(c);check((prior==null||"stable311-qa".equals(prior.accountId))&&!qa.contains("state"),"Only resume this partial synthetic seed; never overwrite real account or checkpoint");long now=System.currentTimeMillis();
   SecureTokenStore.save(c,new AuthTokens("SYNTHETIC_STABLE311_NO_NETWORK","SYNTHETIC_STABLE311_REFRESH","",now+365L*86400000,"stable311-qa",""));AppPreferences.setAutomaticRefresh(c,false);AppPreferences.setRefreshOnLaunch(c,false);AppPreferences.completeOnboarding(c);UpdatePreferences.setAutomaticChecks(c,false);UpdatePreferences.setNotifyUpdatesEnabled(c,false);AppPreferences.setAppTheme(c,"dark");FunStore.tone(c,"off");
   String account=SubscriptionStore.accountKey(c);BetaIdentity.save(c,"정식 전환 검수 Alex");BetaIdentity.prefs(c).edit().putBoolean("setup_done",true).commit();
   long reset=now+3*86400000L;UsageSnapshot sample=new UsageSnapshot("plus",true,false,new UsageWindow(25.25,18000,0,(now+7200000)/1000),new UsageWindow(66.75,604800,0,reset/1000),now);check(AppPreferences.saveSnapshot(c,sample),"Precise cached usage saved");
   JSONObject doc=AccountProgress.empty(),r=RpgEngine.state(doc);AchievementJourney.prepare(doc,now-60L*86400000);TitleJourney.prepare(doc,now-60L*86400000);r.put("collection_revision",CollectionRestart.REVISION).put("xp",46539).put("level",31).put("equipped_title","qa_preserved_title");r.getJSONObject("awards").put("qa_preserved_source",46539);doc.getJSONObject("future").put("qa_preserved",new JSONObject().put("value","must remain"));
   c.getDatabasePath(RpgProgressStore.NAME).getParentFile().mkdirs();try(SQLiteDatabase db=SQLiteDatabase.openOrCreateDatabase(c.getDatabasePath(RpgProgressStore.NAME),null)){db.execSQL("CREATE TABLE IF NOT EXISTS profiles(account TEXT PRIMARY KEY,document TEXT NOT NULL)");db.execSQL("CREATE TABLE IF NOT EXISTS recovery(account TEXT PRIMARY KEY,captured_at INTEGER NOT NULL,document TEXT NOT NULL)");db.setVersion(1);db.execSQL("INSERT OR IGNORE INTO profiles(account,document) VALUES(?,?)",new Object[]{account,doc.toString()});db.execSQL("INSERT OR IGNORE INTO profiles(account,document) VALUES(?,?)",new Object[]{"b".repeat(64),"{\"other_account\":true}"});}
   UsageLedgerDatabase.load(c);try(SQLiteDatabase db=SQLiteDatabase.openDatabase(c.getDatabasePath(UsageLedgerDatabase.NAME).getPath(),null,SQLiteDatabase.OPEN_READWRITE)){for(int i=0;i<2;i++){ContentValues v=new ContentValues();v.put("meter","weekly");v.put("plan","plus");v.put("policy","weekly|plus|604800");v.put("observed_at",now-120000+i*60000);v.put("used",64.25+i*2.5);v.put("used_decimal",Double.toString(64.25+i*2.5));v.put("reset_at",reset);v.put("window_seconds",604800);v.put("source","api_precise");v.put("manual",0);db.insertOrThrow("observations",null,v);}}
   long first=BetaV4.day(now).minusDays(29).atStartOfDay(BetaV4.ZONE).toInstant().toEpochMilli();boolean created=BetaGrowthStore.start(c,account,first,false);check(created||prior!=null&&BetaGrowthStore.load(c,account)!=null,"Opted-in existing growth fixture without resetting partial state");for(int i=0;i<30;i++){LocalDate day=BetaV4.day(first).plusDays(i);if(day.getDayOfWeek().getValue()<=5){long at=day.atTime(1,0).atZone(BetaV4.ZONE).toInstant().toEpochMilli();BetaGrowthStore.confirm(c,account,at,at,false);}}
   check(BetaGrowthStore.equip(c,account,"rpg3.workbench"),"Existing owned title equipped");check(BetaGrowthStore.enabled(c,account,false),"Collection OFF preserved fixture");JSONObject state=BetaGrowthStore.load(c,account),archive=BetaGrowthStore.archive(c,account);check(state.getInt("level")>=30&&archive.getJSONObject("rpg").getLong("xp")==46539,"Nonempty growth and original source retained");
   c.getSharedPreferences("coach_v2",0).edit().putString(account,new JSONObject().put("schemaVersion",2).put("recent",new JSONArray()).put("tips",new JSONArray()).put("hidden",new JSONArray().put("ko.scarce.spicy.001")).toString()).commit();
   check(qa.edit().putString("state",state.toString()).putString("archive",archive.toString()).putString("account",account).putString("name",BetaIdentity.name(c)).putString("tokens",SecureTokenStore.load(c).toJson().toString()).putString("legacy",raw(c,account).toString()).putString("observations",observations(c).toString()).putString("coach",c.getSharedPreferences("coach_v2",0).getString(account,"")).putLong("first_install",info.firstInstallTime).putLong("before_update",info.lastUpdateTime).putInt("uid",c.getApplicationInfo().uid).commit(),"Durable checkpoint committed");
  }else{
   check("stable311-qa".equals(SecureTokenStore.load(c).accountId),"Synthetic account retained");boolean before=phase.equals("before");check(info.versionName.equals(before?"3.1.0":"3.1.1")&&info.getLongVersionCode()==(before?87:88),"Actual installed version/code");check(qa.contains("state"),"Checkpoint retained");check(c.getApplicationInfo().uid==qa.getInt("uid",-1)&&info.firstInstallTime==qa.getLong("first_install",-1),"Same app UID and original install time");if(!before)check(info.lastUpdateTime>qa.getLong("before_update",Long.MAX_VALUE),"Actual APK replacement");
   check(SecureTokenStore.load(c).toJson().toString().equals(qa.getString("tokens","")),"Existing encrypted credentials still decrypt");String account=SubscriptionStore.accountKey(c);check(account.equals(qa.getString("account","")),"Account namespace retained");JSONObject old=new JSONObject(qa.getString("state","")),state=BetaGrowthStore.load(c,account);
   for(String key:new String[]{"rules","namespace","account","cutover","total","level","progress","next_cost","last_response","days","weeks","months","rewards","honors","titles","equipped","enabled","catalog_revision"})check(old.get(key).toString().equals(state.get(key).toString()),"Preserve "+key);
   check(state.optLong("seen_total")>=old.optLong("seen_total")&&state.optLong("seen_total")<=state.getLong("total"),"Acknowledgement cannot award XP");check(BetaGrowthStore.archive(c,account).toString().equals(qa.getString("archive","")),"Exact original archive retained");JSONObject legacy=RpgEngine.state(raw(c,account)),kept=RpgEngine.state(new JSONObject(qa.getString("legacy","")));for(String key:new String[]{"xp","level","awards","equipped_title"})check(legacy.get(key).toString().equals(kept.get(key).toString()),"Legacy source "+key);
   check(raw(c,account).getJSONObject("future").getJSONObject("qa_preserved").toString().equals(new JSONObject(qa.getString("legacy","")).getJSONObject("future").getJSONObject("qa_preserved").toString()),"Unknown future payload preserved while known derived metadata may advance");check(raw(c,"b".repeat(64)).getBoolean("other_account"),"Other account original record retained");check(observations(c).toString().equals(qa.getString("observations","")),"Exact existing usage observations retained");
   check(BetaIdentity.name(c).equals(qa.getString("name",""))&&BetaIdentity.done(c),"Name and completed setup retained");check(AppPreferences.getAppTheme(c).equals("dark")&&FunStore.tone(c).equals("off"),"Theme and coach OFF retained");check(!UpdatePreferences.automaticChecks(c)&&!AppPreferences.getAutomaticRefresh(c)&&!AppPreferences.getRefreshOnLaunch(c),"Update and usage OFF preferences retained");
   check(new JSONObject(c.getSharedPreferences("coach_v2",0).getString(account,"{}")).getJSONArray("hidden").toString().equals(new JSONObject(qa.getString("coach","")).getJSONArray("hidden").toString()),"Stable hidden quote IDs retained");
   for(String file:new String[]{BetaGrowthStore.NAME,UsageLedgerDatabase.NAME,RpgProgressStore.NAME})try(SQLiteDatabase db=SQLiteDatabase.openDatabase(c.getDatabasePath(file).getPath(),null,SQLiteDatabase.OPEN_READONLY);Cursor row=db.rawQuery("PRAGMA integrity_check",null)){check(row.moveToFirst()&&row.getString(0).equals("ok"),"SQLite integrity "+file);}
   check(BetaGrowthStore.export(c,account).getJSONObject("state").getLong("total")==old.getLong("total"),"Backup sees preserved balance");check(UpdatePreferences.installError(c).isEmpty(),"No persisted install failure");
   if(!before){ListHolder.checkComponents(c,this);}
  }
  JSONObject state=BetaGrowthStore.load(c,SubscriptionStore.accountKey(c));out.putString("stream","Stable311 continuity "+phase+": "+checks+" checks passed; Lv."+state.getInt("level")+" / XP "+state.getLong("total")+" / honors "+state.getJSONObject("honors").length()+" / titles "+state.getJSONObject("titles").length()+"; original Lv31 XP46539 fraction39/3100 retained; synthetic only.\n");finish(-1,out);
 }catch(Throwable error){out.putString("stream",android.util.Log.getStackTraceString(error));finish(0,out);}}
 static final class ListHolder {static void checkComponents(Context c,Stable311ContinuityNativeTest t)throws Exception{PackageManager pm=c.getPackageManager();ComponentName wear=new ComponentName(c,"dev.bennett.codexmeter.wear.PhoneWearListenerService");t.check(pm.getServiceInfo(wear,0).enabled,"Wear listener remains enabled");Intent launch=pm.getLaunchIntentForPackage(c.getPackageName());t.check(launch!=null&&launch.getComponent().getClassName().equals(MainActivity.class.getName()),"Stable launcher remains MainActivity");Intent link=new Intent(Intent.ACTION_VIEW,android.net.Uri.parse("codexmeter://auth/complete")).setPackage(c.getPackageName());t.check(pm.resolveActivity(link,PackageManager.MATCH_DEFAULT_ONLY)!=null,"Existing stable auth link resolves");t.check(!TrialDemo.active(c),"Stable account is never presented as demo");boolean denied=false;try{TrialDemo.prepare(c);}catch(IllegalStateException expected){denied=true;}t.check(denied&&"stable311-qa".equals(SecureTokenStore.load(c).accountId),"Production cannot seed trial demo over user data");}}
}
